   boolean haunted=spec.underworld&&FirDecorations.crooked(spec.salt);int radius=Math.max(7,(int)(spec.height*(haunted?.30:.29))),tiers=Math.max(5,spec.height/12);
   for(int tier=0;tier<tiers;tier++){double t=.16+tier*.77/(tiers-1);int dy=(int)(t*spec.height),r=Math.max(2,(int)(radius*(1-t)/.84));boolean straight=!spec.underworld;crowns.add(new HauntedVines.Crown(new HauntedVines.Point(Math.round(FirDecorations.axisX(0,spec.salt,t,spec.height,haunted,straight)),spec.root+spec.direction*dy,Math.round(FirDecorations.axisZ(0,spec.salt,t,spec.height,haunted,straight))),new HauntedVines.Point(0,spec.direction,0),r,r,WorldNoise.mix(spec.salt+tier*73L)));}
