  var rows=new JsonArray();for(String dimension:List.of("guogao","inner","outer")){var level=world(p.level().getServer(),dimension);check(level!=null,"all registered custom dimensions");for(int n=0;n<(dimension.equals("guogao")?4:2);n++){var row=fingerprint(level,32+n%2,32+n/2);row.addProperty("dimension",dimension);if(dimension.equals("guogao"))check(row.get("bottomBedrock").getAsInt()==0,"exact0613 old FULL fixture has no native bedrock floor");rows.add(row);}}
